import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/JavaScript.html","title":"JavaScript","lang":"en-US","frontmatter":{},"git":{"createdTime":1700132732000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":9}]},"readingTime":{"minutes":1.54,"words":463},"filePathRelative":"JavaScript.md"}`),a={name:`JavaScript.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="javascript" tabindex="-1"><a class="header-anchor" href="#javascript"><span>JavaScript</span></a></h1><p>みんな大好きJavaScript</p><ul><li><a href="./Electron.html">Electron</a></li><li><a href="./TypeScript.html">TypeScript</a></li><li><a href="https://2ality.com/2025/08/learning-web-dev-toc.html" target="_blank" rel="noopener noreferrer">New series of blog posts: learning web development</a> 現代的な入門としていいかもしれん。</li><li><a href="./VuePress.html">VuePress</a> nodejs製のサイトジェネレータ</li><li><a href="./zx.html">zx</a></li><li><a href="./Rhino.html">Rhino</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference" target="_blank" rel="noopener noreferrer">JavaScript reference - MDN</a></li></ul><h2 id="プロパティ、getter-setter" tabindex="-1"><a class="header-anchor" href="#プロパティ、getter-setter"><span>プロパティ、getter, setter</span></a></h2><p>プロパティって定義出来たっけ？ってなるのでメモ。</p><p><a href="https://developer.mozilla.org/ja/docs/Web/JavaScript/Reference/Functions/get" target="_blank" rel="noopener noreferrer">get - JavaScript - MDN</a></p><h2 id="optional-chain" tabindex="-1"><a class="header-anchor" href="#optional-chain"><span>Optional Chain</span></a></h2><p>ちょっと予想と違う事があったのでメモ。</p><p><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Optional_chaining" target="_blank" rel="noopener noreferrer">Optional chaining (?.) - JavaScript - MDN</a></p><p>普通はある変数がnullかどうかで効果の出るものだが、これはプロパティアクセスに限定されている。 だからメソッド呼び出しが以下のようにドットが必要になる。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> <span class="token keyword">const</span> adventurer <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;Alice&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>adventurer<span class="token punctuation">.</span>someNonExistentMethod<span class="token operator">?.</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>また、以下のようには書けるが、</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> dogName <span class="token operator">=</span> adventurer<span class="token punctuation">.</span>dog<span class="token operator">?.</span>name<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>以下のようには書けない。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// NG!</span></span>
<span class="line"><span class="token keyword">const</span> mayDog <span class="token operator">=</span> adventurer<span class="token punctuation">.</span>dog<span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>考えてみれば <code>adventurer.dog</code> は無ければundefinedなのだからJSの振る舞い的にはこれが正しいが、</p><p>kotlinとかの言語に慣れていれば、 メソッド呼び出しは <code>hoge?.ika() </code>とhogeの方にはてなをつけそうなものだけど、良く考えるとこれは意味が違う。 JSの例ではhogeがnullかどうかではなく、ikaがあるかどうか、という話をしている。</p><p>でも、例えばインデクサも以下のようになる。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> propName <span class="token operator">=</span> <span class="token string">&quot;x&quot;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> nestedProp <span class="token operator">=</span> obj<span class="token operator">?.</span><span class="token punctuation">[</span>propName<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>これはobjがnullかどうかでは無く、propNameがあるかどうか、というoptionalになっている。配列の範囲外アクセスをundefinedにする感じだ。</p><p>JavaScriptのOptional Chainはnullに対してでは無くundefinedに対してで、undefinedとはそのプロパティが「存在しない」という場合なのでこうした違いがある訳だな。</p><h2 id="nullish-colescing" tabindex="-1"><a class="header-anchor" href="#nullish-colescing"><span>nullish colescing</span></a></h2><p>JSにあったっけ？とたまになるのでメモしておく。</p><p><a href="https://developer.mozilla.org/ja/docs/Web/JavaScript/Reference/Operators/Nullish_coalescing" target="_blank" rel="noopener noreferrer">ヌル値合体演算子 (??) - JavaScript - MDN</a></p><h2 id="arrow-function-expression" tabindex="-1"><a class="header-anchor" href="#arrow-function-expression"><span>Arrow function expression</span></a></h2><p><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Functions/Arrow_functions" target="_blank" rel="noopener noreferrer">Arrow function expressions - JavaScript - MDN</a></p><p>いろいろな言語で似たような機能があるが微妙に違うので毎回迷う。</p><ul><li>アローは <code>=&gt;</code></li><li>expressionならreturnはいらない</li><li>中括弧をつけてstatementを並べる場合はreturnがいる（中括弧をつけると強制的にstatementsとみなされる）</li></ul><h2 id="destructuringのassignment" tabindex="-1"><a class="header-anchor" href="#destructuringのassignment"><span>Destructuringのassignment</span></a></h2><p><a href="./TypeScriptHandbook.html">TypeScriptHandbook</a>を読んでいて、以下の文は既にJavaScriptで存在してしまうので、 以下のようなdestructuringの型指定は出来ない、と書いてあった。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">draw</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">shape</span><span class="token operator">:</span> Shape<span class="token punctuation">,</span> <span class="token literal-property property">xPos</span><span class="token operator">:</span> number <span class="token operator">=</span> <span class="token number">100</span> <span class="token comment">/*...*/</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>へ、どういう意味？と思って見ると、MDNのBinding and assignmentのassignmentの方がその話題だ。</p><p><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Destructuring" target="_blank" rel="noopener noreferrer">Destructuring - JavaScript - MDN</a></p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> numbers <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">a</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">b</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">a</span><span class="token operator">:</span> numbers<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token literal-property property">b</span><span class="token operator">:</span> numbers<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token operator">=</span> obj<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// The properties \`a\` and \`b\` are assigned to properties of \`numbers\`</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>なるほど、変数に代入する感じになるのか。 そしてカッコが無いとブロックになっちゃってオブジェクト式にならないとか。うへぇ。</p><h2 id="arrayのfilterをasyncで使うのが難しい" tabindex="-1"><a class="header-anchor" href="#arrayのfilterをasyncで使うのが難しい"><span>Arrayのfilterをasyncで使うのが難しい</span></a></h2><p><a href="https://stackoverflow.com/questions/47095019/how-to-use-array-prototype-filter-with-async" target="_blank" rel="noopener noreferrer">javascript - How to use Array.prototype.filter with async? - Stack Overflow</a></p><p>信じがたいけれど、本当にこんな事しないといけないのかね。</p><h2 id="jdoc" tabindex="-1"><a class="header-anchor" href="#jdoc"><span>JDoc</span></a></h2><p><a href="https://karino2.github.io/2023/08/19/jsdoc_is_nice.html" target="_blank" rel="noopener noreferrer">JSDocいいね！ - なーんだ、ただの水たまりじゃないか</a></p><p>関数はreturns。</p><p><a href="https://jsdoc.app/tags-returns" target="_blank" rel="noopener noreferrer">Use JSDoc: returns</a></p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token doc-comment comment">/**</span>
<span class="line"> * Returns the sum of a and b</span>
<span class="line"> * <span class="token keyword">@param</span> <span class="token class-name"><span class="token punctuation">{</span>number<span class="token punctuation">}</span></span> <span class="token parameter">a</span></span>
<span class="line"> * <span class="token keyword">@param</span> <span class="token class-name"><span class="token punctuation">{</span>number<span class="token punctuation">}</span></span> <span class="token parameter">b</span></span>
<span class="line"> * <span class="token keyword">@returns</span> <span class="token class-name"><span class="token punctuation">{</span>number<span class="token punctuation">}</span></span></span>
<span class="line"> */</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">sum</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> a <span class="token operator">+</span> b<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="ブックマークレット" tabindex="-1"><a class="header-anchor" href="#ブックマークレット"><span>ブックマークレット</span></a></h2><p>とりあえずここに置いておく。 markdownのリンクとして、けれど縦棒をハイフンに置き換えるブックマークレット。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token literal-property property">javascript</span><span class="token operator">:</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">{</span><span class="token keyword">const</span> e<span class="token operator">=</span>document<span class="token punctuation">.</span><span class="token function">createElement</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span><span class="token keyword">const</span> title <span class="token operator">=</span> document<span class="token punctuation">.</span>title<span class="token punctuation">.</span><span class="token function">replaceAll</span><span class="token punctuation">(</span><span class="token string">&#39;|&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;-&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> e<span class="token punctuation">.</span>value<span class="token operator">=</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">[</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>title<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">](</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>location<span class="token punctuation">.</span>href<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">)</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span>document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;body&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">append</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token punctuation">;</span>e<span class="token punctuation">.</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>document<span class="token punctuation">.</span><span class="token function">execCommand</span><span class="token punctuation">(</span><span class="token string">&#39;copy&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>e<span class="token punctuation">.</span><span class="token function">remove</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token function">alert</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>title<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> copied!</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="jsonc-json5" tabindex="-1"><a class="header-anchor" href="#jsonc-json5"><span>jsonc, json5</span></a></h2><p>JavaScript関係無いがjson関連。</p><p>コメントが入れられるのがjsonc、trailing commaとかもありなのがjson5か。json5でいいのでは感。</p><p><a href="https://paji.blog/jsonc-json5" target="_blank" rel="noopener noreferrer">Paji&#39;s Blog - What is JSONC, what is JSON5.</a></p><h2 id="prismjs" tabindex="-1"><a class="header-anchor" href="#prismjs"><span>prismjs</span></a></h2><p><a href="https://prismjs.com/" target="_blank" rel="noopener noreferrer">Prism</a></p><p>JS製のシンタックスハイライト。小さい。</p><p><a href="./TeFWiki.html">TeFWiki</a>のAndroid版はassetsにprismjsを入れている。こういう用途には小さくて良い。</p><p><a href="./MFG.html">MFG</a>のシンタックスハイライトも以下に用意した。＞<a href="https://github.com/karino2/MFG/tree/main/tools/prism-mfg" target="_blank" rel="noopener noreferrer">MFG/tools/prism-mfg at main · karino2/MFG</a></p>`,55)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};